dashboard.definition:
{
  "title": "Ant Paths",
  "description": "Maps+ ant paths: animated direction flow along vehicle tracks.",
  "dataSources": {
    "ds_in_track_id_viz_3": {
      "type": "ds.search",
      "name": "Vehicle ID choices map 3",
      "options": {
        "query": "| inputlookup go_track_trackspoints.csv | rex field=_time \"(?<date>^\\d+-\\d+-\\d+)\" | search $date_filter_viz_3$ | stats values(track_id) as track_id | mvexpand track_id | sort +track_id",
        "queryParameters": {
          "earliest": "-24h@h",
          "latest": "now"
        }
      }
    },
    "ds_in_date_filter_viz_3": {
      "type": "ds.search",
      "name": "Date choices map 3",
      "options": {
        "query": "| inputlookup go_track_trackspoints.csv | lookup go_track_tracks.csv id as track_id | search $track_id_viz_3$ | rex field=_time \"(?<date>^\\d+-\\d+-\\d+)\" | stats values(date) as day | mvexpand day",
        "queryParameters": {
          "earliest": "-24h@h",
          "latest": "now"
        }
      }
    },
    "ds_map_1": {
      "type": "ds.search",
      "name": "Ant path rows",
      "options": {
        "query": "| inputlookup go_track_trackspoints.csv | lookup go_track_tracks.csv id as track_id | rex field=_time \"(?<date>^\\d+-\\d+-\\d+)\" | search $date_filter_viz_3$ $track_id_viz_3$ | eval markerVisibility=\"hidden\", id=track_id, speed=round(speed, 2), vehicle_type=if(car_or_bus == 1, \"car\", \"bus\"), description=\"car \".id, tooltip=description, pathColor=case(like(id, \"16\"), \"#e50de5\"), pathWeight=case(like(id, \"16\"), \"20\"), pathOpacity=case(like(id, \"16\"), \"1.0\"), antPath=\"true\", layerDescription=case(like(pathLayer, \"cars-16-20\"), \"cars-16-20\", like(pathLayer, \"cars-17-22-23\"), \"cars-17-22-23\"), pathLayer=case(like(id, \"16\"), \"cars-16-20\", like(id, \"17\"), \"cars-17-22-23\", like(id, \"20\"), \"cars-16-20\", like(id, \"22\"), \"cars-17-22-23\", like(id, \"23\"), \"cars-17-22-23\"), layerPriority=case(like(pathLayer, \"cars-16-20\"), 10, like(pathLayer, \"cars-17-22-23\"), 5)",
        "queryParameters": {
          "earliest": "-24h@h",
          "latest": "now"
        }
      }
    }
  },
  "inputs": {
    "input_track_id_viz_3": {
      "type": "input.multiselect",
      "title": "Vehicle ID",
      "options": {
        "token": "track_id_viz_3",
        "defaultValue": "*",
        "items": [
          {
            "label": "All",
            "value": "*"
          }
        ]
      },
      "dataSources": {
        "primary": "ds_in_track_id_viz_3"
      },
      "encoding": {
        "label": "primary.track_id",
        "value": "primary.track_id"
      }
    },
    "input_date_filter_viz_3": {
      "type": "input.multiselect",
      "title": "Date",
      "options": {
        "token": "date_filter_viz_3",
        "defaultValue": "*",
        "items": [
          {
            "label": "All",
            "value": "*"
          }
        ],
        "isCascadingInput": true
      },
      "dataSources": {
        "primary": "ds_in_date_filter_viz_3"
      },
      "encoding": {
        "label": "primary.day",
        "value": "primary.day"
      }
    }
  },
  "visualizations": {
    "viz_html": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "Visualize direction flow with ant paths. Simply `| eval antPath=\"true\" | table antPath` to display the ant path. Control behavior with [the following fields](https://github.com/sghaskell/maps-plus#path-direction).\n\n`antPath`, `antPathDelay`, `antPathPulseColor`, `antPathPaused`, `antPathReverse`, `antPathDashArray`"
      }
    },
    "viz_map_1": {
      "type": "leaflet_maps_app.maps-plus",
      "title": "No Splits, Hidden Markers, Auto Fit & Zoom, pathLayer, pathWeight, pathColor, pathOpacity, tooltip, antPath, layerDescription, layerPriority",
      "dataSources": {
        "primary": "ds_map_1"
      },
      "options": {
        "leaflet_maps_app.maps-plus.allPopups": "0",
        "leaflet_maps_app.maps-plus.animate": "1",
        "leaflet_maps_app.maps-plus.autoFitAndZoom": "1",
        "leaflet_maps_app.maps-plus.autoFitAndZoomDelay": "500",
        "leaflet_maps_app.maps-plus.bingMaps": "0",
        "leaflet_maps_app.maps-plus.bingMapsLabelLanguage": "en-US",
        "leaflet_maps_app.maps-plus.bingMapsTileLayer": "CanvasLight",
        "leaflet_maps_app.maps-plus.cluster": "1",
        "leaflet_maps_app.maps-plus.contextMenu": "1",
        "leaflet_maps_app.maps-plus.criticalThreshold": "80",
        "leaflet_maps_app.maps-plus.defaultHeight": "600",
        "leaflet_maps_app.maps-plus.disableClusteringAtZoom": "0",
        "leaflet_maps_app.maps-plus.drilldown": "0",
        "leaflet_maps_app.maps-plus.drilldownAction": "dblclick",
        "leaflet_maps_app.maps-plus.fullScreen": "0",
        "leaflet_maps_app.maps-plus.googlePlacesPosition": "topleft",
        "leaflet_maps_app.maps-plus.googlePlacesSearch": "0",
        "leaflet_maps_app.maps-plus.googlePlacesZoomLevel": "12",
        "leaflet_maps_app.maps-plus.heatmapBlur": "15",
        "leaflet_maps_app.maps-plus.heatmapColorGradient": "{\"0.4\":\"blue\",\"0.6\":\"cyan\",\"0.7\":\"lime\",\"0.8\":\"yellow\",\"1\":\"red\"}",
        "leaflet_maps_app.maps-plus.heatmapEnable": "0",
        "leaflet_maps_app.maps-plus.heatmapMaxPointIntensity": "1.0",
        "leaflet_maps_app.maps-plus.heatmapMaxZoom": "0",
        "leaflet_maps_app.maps-plus.heatmapMinOpacity": "1.0",
        "leaflet_maps_app.maps-plus.heatmapOnly": "0",
        "leaflet_maps_app.maps-plus.heatmapRadius": "25",
        "leaflet_maps_app.maps-plus.i18nLanguage": "en",
        "leaflet_maps_app.maps-plus.layerControl": "1",
        "leaflet_maps_app.maps-plus.layerControlCollapsed": "1",
        "leaflet_maps_app.maps-plus.mapCenterLat": "-10.698394",
        "leaflet_maps_app.maps-plus.mapCenterLon": "-37.026672",
        "leaflet_maps_app.maps-plus.mapCenterZoom": "9",
        "leaflet_maps_app.maps-plus.mapTile": "http://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png",
        "leaflet_maps_app.maps-plus.maxClusterRadius": "80",
        "leaflet_maps_app.maps-plus.maxSpiderfySize": "100",
        "leaflet_maps_app.maps-plus.maxZoom": "19",
        "leaflet_maps_app.maps-plus.measureActiveColor": "#00ff00",
        "leaflet_maps_app.maps-plus.measureCompletedColor": "#0066ff",
        "leaflet_maps_app.maps-plus.measureIconPosition": "topright",
        "leaflet_maps_app.maps-plus.measureLocalization": "en",
        "leaflet_maps_app.maps-plus.measurePrimaryAreaUnit": "acres",
        "leaflet_maps_app.maps-plus.measurePrimaryLengthUnit": "feet",
        "leaflet_maps_app.maps-plus.measureSecondaryAreaUnit": "sqmiles",
        "leaflet_maps_app.maps-plus.measureSecondaryLengthUnit": "miles",
        "leaflet_maps_app.maps-plus.measureTool": "1",
        "leaflet_maps_app.maps-plus.minZoom": "1",
        "leaflet_maps_app.maps-plus.multiplePopups": "0",
        "leaflet_maps_app.maps-plus.pathColorList": "#0003F0,#D43C29,darkgreen,0xe2d400,darkred,#23A378",
        "leaflet_maps_app.maps-plus.pathIdentifier": "track_id",
        "leaflet_maps_app.maps-plus.pathSplitInterval": "30",
        "leaflet_maps_app.maps-plus.pathSplits": "0",
        "leaflet_maps_app.maps-plus.permanentTooltip": "0",
        "leaflet_maps_app.maps-plus.rangeOneBgColor": "#B5E28C",
        "leaflet_maps_app.maps-plus.rangeOneFgColor": "#6ECC39",
        "leaflet_maps_app.maps-plus.rangeThreeBgColor": "#FD9C73",
        "leaflet_maps_app.maps-plus.rangeThreeFgColor": "#F18017",
        "leaflet_maps_app.maps-plus.rangeTwoBgColor": "#F1D357",
        "leaflet_maps_app.maps-plus.rangeTwoFgColor": "#F0C20C",
        "leaflet_maps_app.maps-plus.refreshInterval": "0",
        "leaflet_maps_app.maps-plus.renderer": "canvas",
        "leaflet_maps_app.maps-plus.scrollWheelZoom": "1",
        "leaflet_maps_app.maps-plus.showPathLines": "1",
        "leaflet_maps_app.maps-plus.showProgress": "1",
        "leaflet_maps_app.maps-plus.singleMarkerMode": "0",
        "leaflet_maps_app.maps-plus.spiderfyDistanceMultiplier": "1",
        "leaflet_maps_app.maps-plus.stickyTooltip": "1",
        "leaflet_maps_app.maps-plus.warningThreshold": "55",
        "leaflet_maps_app.maps-plus.useOpenFreeMap": "1",
        "leaflet_maps_app.maps-plus.maplibreStylePreset": "positron"
      }
    },
    "viz_md_1": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "### Ant paths with styled layers\n\n**What this shows** - Vehicle tracks drawn as animated ant paths (direction of travel), grouped into two layers; markers are hidden.\n\n**The SPL**\n\n```spl\n| inputlookup go_track_trackspoints.csv | lookup go_track_tracks.csv id as track_id | rex field=_time \"(?<date>^\\d+-\\d+-\\d+)\" | search $$date_filter_viz_3$$ $$track_id_viz_3$$ | eval markerVisibility=\"hidden\", id=track_id, speed=round(speed, 2), vehicle_type=if(car_or_bus == 1, \"car\", \"bus\"), description=\"car \".id, tooltip=description, pathColor=case(like(id, \"16\"), \"#e50de5\"), pathWeight=case(like(id, \"16\"), \"20\"), pathOpacity=case(like(id, \"16\"), \"1.0\"), antPath=\"true\", layerDescription=case(like(pathLayer, \"cars-16-20\"), \"cars-16-20\", like(pathLayer, \"cars-17-22-23\"), \"cars-17-22-23\"), pathLayer=case(like(id, \"16\"), \"cars-16-20\", like(id, \"17\"), \"cars-17-22-23\", like(id, \"20\"), \"cars-16-20\", like(id, \"22\"), \"cars-17-22-23\", like(id, \"23\"), \"cars-17-22-23\"), layerPriority=case(like(pathLayer, \"cars-16-20\"), 10, like(pathLayer, \"cars-17-22-23\"), 5)\n```\n\n**How it works**\n\n1. `inputlookup go_track_trackspoints.csv` plus `lookup go_track_tracks.csv id as track_id` gives points with `latitude`, `longitude`, `track_id`, `_time` and track details; `rex` and `search $$date_filter_viz_3$$ $$track_id_viz_3$$` apply the input filters.\n2. `eval` hides the markers (`markerVisibility`), sets `description` / `tooltip`, and styles vehicle 16 with `pathColor`, `pathWeight`, `pathOpacity`.\n3. `antPath=\"true\"` on every row turns each path into an animated ant path. A path's style comes from its first row.\n4. `pathLayer`, `layerDescription` and `layerPriority` group vehicles into two layers; `pathIdentifier=track_id` splits rows into paths and `showPathLines=1` enables them.\n5. Gotcha: `eval` runs left to right, so `layerDescription` tests `pathLayer` before it is assigned.\n\n**Field formats and rules**\n\n| Field | Expected format | Rule / gotcha |\n|---|---|---|\n| `latitude` | decimal degrees (number) | Exact lowercase name. Here it comes straight from the lookup. Every row is a path vertex, so every row needs coordinates. |\n| `longitude` | decimal degrees (number) | Exact lowercase name. |\n| `_time` | timestamp Maps+ can parse | Used by `pathSplits` and playback. Maps+ never sorts: rows are drawn in result order, and this query relies on the lookup's row order. |\n| `track_id` | any text; the field named in `pathIdentifier` | Splits rows into paths. Without `pathIdentifier`, all rows form one path. |\n| `description` | HTML text | Click popup; a path takes it from its first row. Escape any event text you put in it. |\n| `tooltip` | HTML text | Hover tooltip; a path takes it from its first row. |\n| `antPath` | `\"true\"` per row | Draws an animated path; any other value draws a plain path. |\n| `markerVisibility` | `\"true\"` / `\"marker\"` shows; anything else hides | Every row also draws a marker; this hides them so only the path shows. The documented off value is `\"false\"`. |\n| `pathColor` | CSS colour | Default is the next colour in `pathColorList`. A path's style comes from its first row. |\n| `pathWeight` | integer, default 5 | Line width in pixels. |\n| `pathOpacity` | 0 to 1, default 0.5 | Line opacity. |\n| `pathLayer` | text | Layer-control entry for the path (default: the path id). |\n| `layerDescription` | HTML text | Label in the layer control; for path layers the first row wins. |\n| `layerPriority` | integer | Pane order of the layer. |\n\n**Try it**\n\n- Append `, antPathDelay=\"400\", antPathPulseColor=\"#ffff00\"` to the `eval` for faster, yellow pulses (defaults: 1000 and `#FFFFFF`).\n- Append `, antPathDashArray=\"5,10\"` to change the dash pattern (default `10,20`). `antPathPaused` and `antPathReverse` are true for any non-empty value, so leave them null to turn them off.\n\n> **Studio note:** Studio multiselect inputs ignore the classic prefix (`track_id=`), `valuePrefix`/`valueSuffix` and `delimiter`; values are comma-joined with no wrapping, so the token no longer expands to `track_id=\"16\" OR track_id=\"17\"`. Only the **All** choice (`*`) gives a valid filter, so the inputs default to All. The query text is unchanged. On Maps+ 4.6.9 and earlier, a Studio cell that is null counts as set (the `case()` fields below are null for non-matching rows); fixed in the unreleased 4.6.10.\n\n**Basemap:** this example uses keyless OpenFreeMap vector tiles (`useOpenFreeMap` = 1). CARTO basemaps need a free API key: see **Help > Basemaps & API keys** for how to get one and where to put it (**Map Tile Override**)."
      }
    }
  },
  "layout": {
    "globalInputs": [
      "input_track_id_viz_3",
      "input_date_filter_viz_3"
    ],
    "tabs": {
      "items": [
        {
          "label": "New tab",
          "layoutId": "layout_1"
        }
      ]
    },
    "layoutDefinitions": {
      "layout_1": {
        "type": "absolute",
        "options": {
          "width": 1440,
          "height": 850,
          "display": "auto",
          "backgroundColor": "#FFFFFF"
        },
        "structure": [
          {
            "item": "viz_html",
            "type": "block",
            "position": {
              "x": 0,
              "y": 0,
              "w": 1440,
              "h": 150
            }
          },
          {
            "item": "viz_map_1",
            "type": "block",
            "position": {
              "x": 0,
              "y": 150,
              "w": 880,
              "h": 700
            }
          },
          {
            "item": "viz_md_1",
            "type": "block",
            "position": {
              "x": 880,
              "y": 150,
              "w": 560,
              "h": 700
            }
          }
        ]
      }
    }
  }
}
